import { useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useStore } from '../store/useStore'
import { Tenant } from '../types'
import TenantModal from '../components/TenantModal'
import BillModal from '../components/BillModal'
import { ChevronLeft, User, Phone, Calendar, Plus, FileText } from 'lucide-react'

export default function RoomDetail() {
  const { propertyId, roomId } = useParams<{ propertyId: string; roomId: string }>()
  const navigate = useNavigate()
  const { properties, rooms, tenants, bills, updateTenant, addBill, createTenantContract, terminateTenant } = useStore()

  const property = properties.find(p => p.id === propertyId)
  const room = rooms.find(r => r.id === roomId)
  const tenant = tenants.find(t => t.roomId === roomId)
  const roomBills = bills.filter(b => b.roomId === roomId && b.direction === 'receivable')

  const [showTenantModal, setShowTenantModal] = useState(false)
  const [showBillModal, setShowBillModal] = useState(false)
  const [editingTenant, setEditingTenant] = useState<Tenant | undefined>()
  const [extendDate, setExtendDate] = useState('')
  const [showExtend, setShowExtend] = useState('')

  const handleExtend = () => {
    if (!extendDate || !tenant) return
    useStore.getState().extendContract(tenant.id, extendDate)
    setShowExtend('')
    setExtendDate('')
  }

  const typeLabels: Record<string, string> = {
    rent: '房租',
    water: '水费',
    electric: '电费',
    gas: '燃气费',
    other: '其他',
  }

  const statusClasses: Record<string, string> = {
    pending: 'bg-yellow-100 text-yellow-700',
    paid: 'bg-green-100 text-green-700',
    overdue: 'bg-red-100 text-red-700',
  }

  const statusLabels: Record<string, string> = {
    pending: '未收',
    paid: '已收',
    overdue: '已逾期',
  }

  if (!room) {
    return (
      <div className="min-h-screen bg-gray-50 pb-24 flex items-center justify-center">
        <p className="text-gray-500">房间不存在</p>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      <div className="bg-white border-b border-gray-100 px-4 pt-10 pb-6">
        <div className="max-w-md mx-auto">
          <div className="flex items-center gap-3 mb-4">
            <button
              type="button"
              onClick={() => navigate(`/properties/${propertyId}`)}
              className="p-1 hover:bg-gray-100 rounded-lg"
            >
              <ChevronLeft className="w-6 h-6 text-gray-600" />
            </button>
            <div>
              <h1 className="text-xl font-bold text-gray-900">
                {property?.address} - {room.label} 室
              </h1>
              <p className="text-sm text-gray-500">{room.roomType}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="px-4 pt-6">
        <div className="max-w-md mx-auto space-y-6">
          {/* 租客信息 */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-lg font-semibold text-gray-900">
                <User className="w-5 h-5 inline mr-1" />
                租客信息
              </h2>
              {tenant && (
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={() => {
                      setEditingTenant(tenant)
                      setShowTenantModal(true)
                    }}
                    className="text-sm text-blue-600 hover:underline"
                  >
                    编辑
                  </button>
                  {tenant.status === 'active' && (
                    <>
                      <button
                        type="button"
                        onClick={() => setShowExtend(tenant.id)}
                        className="text-sm text-green-600 hover:underline"
                      >
                        续约
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          if (confirm(`确定要退租吗？${tenant.name}的合同将终止，房间将释放。`)) {
                            terminateTenant(tenant.id, roomId!)
                          }
                        }}
                        className="text-sm text-red-600 hover:underline"
                      >
                        退租
                      </button>
                    </>
                  )}
                </div>
              )}
            </div>

            {tenant ? (
              <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-4">
                <div className="flex items-center gap-2 mb-3">
                  <span className="text-sm font-medium text-gray-900">{tenant.name}</span>
                  <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${tenant.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-500'}`}>
                    {tenant.status === 'active' ? '在租' : '已退租'}
                  </span>
                </div>
                <div className="space-y-2">
                  {tenant.phone && (
                    <div className="flex items-center gap-2 text-sm text-gray-600">
                      <Phone className="w-4 h-4 text-gray-400" />
                      <span>{tenant.phone}</span>
                    </div>
                  )}
                  <div className="flex items-center gap-2 text-sm text-gray-600">
                    <Calendar className="w-4 h-4 text-gray-400" />
                    <span>合同期：{tenant.contractStart} 至 {tenant.contractEnd}</span>
                  </div>
                </div>

                {/* 续约弹窗 */}
                {showExtend === tenant.id && (
                  <div className="mt-3 pt-3 border-t border-gray-100">
                    <label className="block text-sm font-medium text-gray-700 mb-2">新合同到期日</label>
                    <div className="flex gap-2">
                      <input
                        type="date"
                        value={extendDate}
                        onChange={(e) => setExtendDate(e.target.value)}
                        className="flex-1 px-3 py-2 border border-gray-200 rounded-lg text-sm"
                      />
                      <button
                        type="button"
                        onClick={handleExtend}
                        className="px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-medium hover:bg-green-700"
                      >
                        确认
                      </button>
                      <button
                        type="button"
                        onClick={() => { setShowExtend(''); setExtendDate('') }}
                        className="px-4 py-2 bg-gray-100 text-gray-600 rounded-lg text-sm"
                      >
                        取消
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center py-8 bg-white rounded-2xl shadow-sm border border-gray-100">
                <User className="w-10 h-10 text-gray-300 mx-auto mb-2" />
                <p className="text-gray-500 mb-3">暂无租客</p>
                <button
                  type="button"
                  onClick={() => {
                    setEditingTenant(undefined)
                    setShowTenantModal(true)
                  }}
                  className="px-6 py-2 bg-blue-600 text-white rounded-xl text-sm font-medium hover:bg-blue-700 transition-colors"
                >
                  添加租客
                </button>
              </div>
            )}
          </div>

          {/* 租客账单 */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-lg font-semibold text-gray-900">
                <FileText className="w-5 h-5 inline mr-1" />
                租客账单
              </h2>
              <button
                type="button"
                onClick={() => setShowBillModal(true)}
                className="text-sm text-blue-600 hover:underline flex items-center gap-1"
              >
                <Plus className="w-4 h-4" />
                添加
              </button>
            </div>

            <div className="space-y-2">
              {roomBills.length === 0 ? (
                <div className="text-center py-8 bg-white rounded-2xl shadow-sm border border-gray-100">
                  <p className="text-gray-500">暂无账单</p>
                </div>
              ) : (
                roomBills.map((bill) => (
                  <div key={bill.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-4">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center gap-2">
                        <span className="font-medium text-gray-900">{typeLabels[bill.type]}</span>
                        <span className={`px-2 py-0.5 rounded-full text-xs font-medium ${statusClasses[bill.status]}`}>
                          {statusLabels[bill.status]}
                        </span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-lg font-bold text-gray-900">
                          {bill.paidAmount !== undefined && bill.paidAmount < bill.amount
                            ? `¥${bill.paidAmount.toFixed(2)}/¥${bill.amount.toFixed(2)}`
                            : `¥${bill.amount.toFixed(2)}`}
                        </span>
                        {bill.paidAmount !== undefined && bill.paidAmount < bill.amount && (
                          <span className="text-xs bg-orange-100 text-orange-700 px-1.5 py-0.5 rounded">部分</span>
                        )}
                      </div>
                    </div>
                    <div className="text-xs text-gray-400">
                      {bill.description && <div className="mb-1">{bill.description}</div>}
                      <span>应收日：{bill.dueDate}</span>
                      {bill.paidDate && <span className="ml-2">实收：{bill.paidDate}</span>}
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>

      <TenantModal
        isOpen={showTenantModal}
        onClose={() => setShowTenantModal(false)}
        onSave={(data) => {
          if (editingTenant) {
            updateTenant(editingTenant.id, data)
          }
          setEditingTenant(undefined)
          setShowTenantModal(false)
        }}
        onContractConfirm={(tenantData, draftBills) => {
          createTenantContract(tenantData, draftBills, roomId!)
          setShowTenantModal(false)
        }}
        properties={properties}
        rooms={rooms}
        editingTenant={editingTenant}
        selectedRoomId={roomId}
      />

      <BillModal
        isOpen={showBillModal}
        onClose={() => setShowBillModal(false)}
        onSave={(data) => {
          addBill(data)
          setShowBillModal(false)
        }}
        properties={properties}
        rooms={rooms}
        tenants={tenants}
        defaultRoomId={roomId}
        defaultDirection="receivable"
      />
    </div>
  )
}
