import { useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useStore } from '../store/useStore'
import { RoomLabel } from '../types'
import RoomCard from '../components/RoomCard'
import RoomModal from '../components/RoomModal'
import LandlordContractModal from '../components/LandlordContractModal'
import { Plus, ChevronLeft, FileText } from 'lucide-react'

export default function RoomList() {
  const { propertyId } = useParams<{ propertyId: string }>()
  const navigate = useNavigate()
  const { properties, rooms, tenants, addRoom, addBill } = useStore()

  const property = properties.find(p => p.id === propertyId)
  const propertyRooms = rooms.filter(r => r.propertyId === propertyId)
  const getTenantForRoom = (rid: string) => tenants.find(t => t.roomId === rid)

  const [showModal, setShowModal] = useState(false)
  const [editingRoomId, setEditingRoomId] = useState<string | null>(null)
  const [showLandlordContract, setShowLandlordContract] = useState(false)

  if (!property) {
    return (
      <div className="min-h-screen bg-gray-50 pb-24 flex items-center justify-center">
        <p className="text-gray-500">房源不存在</p>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 pb-24">
      <div className="bg-white border-b border-gray-100 px-4 pt-10 pb-6">
        <div className="max-w-md mx-auto">
          <div className="flex items-center gap-3 mb-4">
            <button
              type="button"
              onClick={() => navigate('/properties')}
              className="p-1 hover:bg-gray-100 rounded-lg"
            >
              <ChevronLeft className="w-6 h-6 text-gray-600" />
            </button>
            <div>
              <h1 className="text-xl font-bold text-gray-900">{property.address}</h1>
              <p className="text-sm text-gray-500">{propertyRooms.length} 间房间</p>
            </div>
          </div>
        </div>
      </div>

      <div className="px-4 pt-6">
        <div className="max-w-md mx-auto">
          {/* 业主合同 */}
          <div className="mb-6">
            <button
              type="button"
              onClick={() => setShowLandlordContract(true)}
              className="w-full bg-white rounded-2xl shadow-sm border border-dashed border-orange-300 p-4 flex items-center gap-4 hover:shadow-md transition-shadow cursor-pointer"
            >
              <div className="w-12 h-12 bg-orange-100 rounded-xl flex items-center justify-center">
                <FileText className="w-6 h-6 text-orange-600" />
              </div>
              <div className="flex-1 text-left">
                <p className="font-medium text-gray-900">业主合同</p>
                <p className="text-sm text-gray-500">管理整栋楼的应付房租账单</p>
              </div>
              <ChevronLeft className="w-5 h-5 text-gray-300 rotate-180" />
            </button>
          </div>

          <div className="space-y-3">
            {propertyRooms.map((room) => (
              <div key={room.id} className="relative">
                <RoomCard
                  room={room}
                  tenant={getTenantForRoom(room.id)}
                  onClick={() => navigate(`/properties/${propertyId}/rooms/${room.id}`)}
                />
              </div>
            ))}
            {propertyRooms.length === 0 && (
              <div className="text-center py-12">
                <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Plus className="w-10 h-10 text-gray-400" />
                </div>
                <p className="text-gray-500">暂无房间</p>
                <p className="text-sm text-gray-400 mt-1">点击下方按钮添加房间</p>
              </div>
            )}
          </div>

          {propertyRooms.length < 5 && (
            <button
              type="button"
              onClick={() => {
                setEditingRoomId(null)
                setShowModal(true)
              }}
              className="w-full mt-6 bg-blue-900 text-white py-4 rounded-2xl font-medium hover:bg-blue-800 transition-colors flex items-center justify-center gap-2 cursor-pointer"
            >
              <Plus className="w-5 h-5" />
              添加房间
            </button>
          )}
        </div>
      </div>

      <RoomModal
        isOpen={showModal}
        onClose={() => setShowModal(false)}
        onSave={(data) => {
          addRoom(data)
          setShowModal(false)
        }}
        propertyId={propertyId!}
        editingRoom={editingRoomId ? rooms.find(r => r.id === editingRoomId) : undefined}
        usedLabels={propertyRooms.map(r => r.label) as RoomLabel[]}
      />

      <LandlordContractModal
        isOpen={showLandlordContract}
        onClose={() => setShowLandlordContract(false)}
        onConfirm={(draftBills) => {
          draftBills.forEach((bill) => {
            addBill({
              propertyId: propertyId!,
              amount: bill.amount,
              type: 'rent',
              status: 'pending',
              direction: 'payable',
              dueDate: bill.dueDate,
              description: bill.description,
            })
          })
          setShowLandlordContract(false)
        }}
        propertyAddress={property?.address || ''}
      />
    </div>
  )
}
